with with_windows as (select id, location, budget, lead(budget, 1) over (partition by location order by budget, id) as next_budget, max(budget) over (partition by location) as location_max_budget, sum(budget) over (order by budget, id rows between unbounded preceding and current row) as running_budget, cume_dist() over (partition by dept_name order by budget) as budget_cume_dist from departments where location in ('Berlin', 'Bangkok')) select case when location_max_budget >= 3139113 then 'LARGE' else 'SMALL' end as location_max_budget_tier, count_if(location = 'Bangkok') as bangkok_events, approx_percentile(running_budget, 0.95) as running_budget_p95, count(*) filter (where location = 'Tokyo') as tokyo_rows from with_windows group by location_max_budget_tier order by location_max_budget_tier desc;
